    feed.emit(OutcomeEvent(kind="run.done", task_id="task_1", goal_id="g1", passed=True))
    feed.emit(OutcomeEvent(kind="run.evaluated", task_id="task_1", goal_id="g1", passed=None))

    assert strategy.get("g1").health == "unknown"
