def test_duplicate_team_verdict_is_not_counted_or_prioritised_twice(tmp_path):
    listener, feed, strategy, _ = _wire(
        tmp_path,
        StrategyRecord(
            goal_id="g1",
            score=0.2,
            root_task_id="root-1",
            delivery_shape="team",
        ),
    )
    listener.start()
    event = OutcomeEvent(kind="run.evaluated", task_id="child-1", goal_id="g1", passed=False)

    feed.emit(event)
    feed.emit(event)

    record = strategy.get("g1")
    assert (record.fails, record.score, listener.handled) == (1, 0.45, 1)
